//1 - Write a JavaScript function that returns a string that has letters in alphabetical order.
//ex:-webmaster

function stringconvert(str) {
    return str.split('').sort().join(' ')
}

let input_str = "webmaster";
let sorting_str = stringconvert(input_str);
console.log(sorting_str);


//2 - Write a JavaScript function that accepts a string as a parameter and converts the first letter of each word into upper case.
// Example string : 'the quick brown fox'

function toUpper(str1) {
    return str1.toUpperCase();
}

let input_str1 = 'the quick brown fox';
let uppercase_str1 = toUpper(input_str1);
console.log(uppercase_str1);

//3 - Write a JavaScript function that accepts a string as a parameter and counts the number of vowels within the string.
//Note : As the letter 'y' can be regarded as both a vowel and a consonant, we do not count 'y' as vowel here.
//Example string : 'The quick brown fox'

const vowels = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'];
let str2 = 'The quick brown fox';
let split_str2 = str2.split('');

console.log(split_str2);

let calculate = split_str2.filter(x => vowels.includes(x)).length;

console.log(calculate);


//4 - Write a JavaScript function that takes an array of numbers and finds the second lowest and second greatest numbers, respectively.
//Sample array : [1,2,3,4,5]
//Expected Output : 2,4

let num = [12, 13, 152, 3, 5, 6, 81, 52]

 num.sort((x, y) => y - x);
console.log(num.sort((x, y) => y - x));
console.log(`Second Lowest ${num[6]}`);
console.log(`Second greatest ${num[1]}`);

